// Package orders keeps running order totals per customer, fed by placed
// orders.
package orders

import (
	"context"
	"time"
)

// Placed says order ID was placed by a customer.
type Placed struct {
	ID       int
	Customer int
	Total    int
}

// RejectedError is an order the indexer refuses to count.
type RejectedError struct {
	Reason string
}

func (e *RejectedError) Error() string { return "rejected: " + e.Reason }

// Retry is how often a failed message is retried, and the wait between
// attempts.
type Retry struct {
	Max     int
	Backoff time.Duration
}

// Indexer adds every placed order to its customer's total, once per order
// id.
type Indexer struct {
	Totals  *Repo[int, int]  // customer → running total
	Counted *Repo[int, bool] // ids of orders already added to a total
	Retry   Retry
	Dead    []Placed // messages that failed every attempt
}

// NewIndexer is an indexer over empty stores.
func NewIndexer() *Indexer {
	return &Indexer{
		Totals:  NewRepo[int, int](),
		Counted: NewRepo[int, bool](),
		Retry:   Retry{Max: 2, Backoff: 10 * time.Millisecond},
	}
}

// Perform adds m to its customer's total unless it was counted before.
func (ix *Indexer) Perform(m Placed) error {
	if m.Total < 0 {
		return &RejectedError{"negative total"}
	}
	if _, ok := ix.Counted.Get(m.ID); ok {
		return nil
	}
	current, _ := ix.Totals.Get(m.Customer)
	ix.Totals.Put(m.Customer, current+m.Total)
	ix.Counted.Put(m.ID, true)
	return nil
}

// Deliver performs m, retrying as ix.Retry says, and dead-letters it when
// every attempt fails.
func (ix *Indexer) Deliver(m Placed) {
	for attempt := 0; ; attempt++ {
		if ix.Perform(m) == nil {
			return
		}
		if attempt == ix.Retry.Max {
			ix.Dead = append(ix.Dead, m)
			return
		}
		time.Sleep(ix.Retry.Backoff)
	}
}

// Run delivers each placed order until placed is closed or ctx is done.
func (ix *Indexer) Run(ctx context.Context, placed <-chan Placed) {
	for {
		select {
		case <-ctx.Done():
			return
		case m, ok := <-placed:
			if !ok {
				return
			}
			ix.Deliver(m)
		}
	}
}

package orders

import (
	"maps"
	"slices"
	"sync"
)

// Repo is an in-process key-value store, safe for concurrent use.
type Repo[K comparable, V any] struct {
	mu sync.Mutex
	m  map[K]V
}

// NewRepo is an empty store.
func NewRepo[K comparable, V any]() *Repo[K, V] {
	return &Repo[K, V]{m: map[K]V{}}
}

// Get is the value stored at k, and whether there is one.
func (r *Repo[K, V]) Get(k K) (V, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	v, ok := r.m[k]
	return v, ok
}

// Put stores v at k.
func (r *Repo[K, V]) Put(k K, v V) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.m[k] = v
}

// Delete removes k.
func (r *Repo[K, V]) Delete(k K) {
	r.mu.Lock()
	defer r.mu.Unlock()
	delete(r.m, k)
}

// All is every stored value, in no particular order.
func (r *Repo[K, V]) All() []V {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Collect(maps.Values(r.m))
}

package orders

import "testing"

func TestPlacedOrdersAreTotalledPerCustomer(t *testing.T) {
	ix := NewIndexer()
	ix.Deliver(Placed{ID: 1, Customer: 7, Total: 30})
	ix.Deliver(Placed{ID: 2, Customer: 7, Total: 12})
	ix.Deliver(Placed{ID: 3, Customer: 8, Total: 5})
	if got, ok := ix.Totals.Get(7); !ok || got != 42 {
		t.Errorf("total of 7 = %d, %v; want 42", got, ok)
	}
	if got, ok := ix.Totals.Get(8); !ok || got != 5 {
		t.Errorf("total of 8 = %d, %v; want 5", got, ok)
	}
}

func TestARejectedOrderIsDeadLetteredAndCountsNothing(t *testing.T) {
	ix := NewIndexer()
	ix.Deliver(Placed{ID: 4, Customer: 9, Total: -1})
	if got, ok := ix.Totals.Get(9); ok {
		t.Errorf("total of 9 = %d, want none", got)
	}
	if len(ix.Dead) != 1 {
		t.Errorf("dead letters = %v, want the order", ix.Dead)
	}
}

func TestARedeliveredOrderIsCountedOnce(t *testing.T) {
	ix := NewIndexer()
	ix.Deliver(Placed{ID: 5, Customer: 10, Total: 8})
	ix.Deliver(Placed{ID: 5, Customer: 10, Total: 8})
	if got, ok := ix.Totals.Get(10); !ok || got != 8 {
		t.Errorf("total of 10 = %d, %v; want 8", got, ok)
	}
}
